program.# The query buttons on their panel. Each:
# Spørreknappene på panelet sitt. Hver sender skjermbildet til Google:
#   name: knappens verktøytips;
#   mode: hvor skjermbildet går:
#     "ai": Googles AI svarer på miniprompten med ord over resultatene for
#       bildet og spørsmålet;
#     "chat": selve AI-modus (google.com/ai) i programmets vindu: programmet legger inn
#       skjermbildet og spørsmålet der og sender dem; vinduet dukker opp ved siden av
#       markeringen med bare samtalen og feltet for neste spørsmål; holdes knappen inne,
#       stiller den ditt eget spørsmål med stemmen i stedet for miniprompten, så lenge den
#       holdes inne;
#     "answer": det samme med vinduet skjult: svaret vises i et kort ved siden av
#       markeringen;
#     "images": bildesøket uten spørsmål, i programmets vindu ved siden av markeringen:
#       med en gang de nøyaktige treffene, sidene med akkurat dette bildet, der titlene
#       ofte sier hvem eller hva som er på det;
#   prompt: miniprompten, spørsmålet til AI-en, for "ai", "chat" og "answer";
#   key: knappens tast mens skjermen er frosset;
#   icon: "google", "translate", "images" eller "question".
# AI-knappene står først på panelet, bildesøket etter dem.
# Du logger på Google i programmets vindu fra innstillingsvinduet, «Google-konto»;
# så lenge ingen er logget på, tilbyr programmet pålogging når det starter.
